#include <iostream>
#include <typeinfo>
struct Base { virtual ~Base() = default; };
struct Derived : Base {};
int main() {
    Derived d;
    Base& b = d;
    std::cout << (typeid(b) == typeid(Derived) ? "Derived" : "Base") << '\n';
    std::cout << (typeid(b) == typeid(Base) ? "Base" : "notBase");
}
